/**
 * LESSON PLAN — reverse-engineered from `GFr3LPFull_Copy.pdf`
 * (Grade 3 Life Skills · Personal and Social Well-being · Basic First Aid).
 *
 * The anatomy is NOT defined here: it lives in `lesson-plan-contract.ts`, which
 * every lesson-plan prompt in the app imports. That is deliberate — the same
 * eight blocks and the same five timed phases must appear whether the plan is
 * generated by the classic doctrine, the LIGHT v5 doctrine, the CAPS
 * lesson-plan service or any alternative model.
 */

import type { ContentTypeTemplate, TemplatePromptInput } from './types';
import { MEASURED_LAYOUT, resolveMeasuredPalette, measuredPaletteBrief } from './visual-system';
import {
  LESSON_PLAN_CONTENT_CONTRACT,
  LESSON_PLAN_WORKSHEET_CONTRACT,
  lessonPhaseTable,
  scaleLessonPhases,
} from './lesson-plan-contract';
import {
  SA_PUBLISHER_IDENTITY,
  composeSystemPrompt,
  composeUserPrompt,
  illustrationClause,
  requestBlock,
} from './shared';

const systemPrompt = composeSystemPrompt({
  role: `${SA_PUBLISHER_IDENTITY}

Your document is a LESSON PLAN: a teacher's working script for one lesson, written so that a substitute teacher with no preparation can walk in and teach it. It is not a worksheet and not a summary of the topic — it is the plan of what the teacher does, minute by minute, and what the learners do in response.`,
  visual: `VISUAL SYSTEM (measured from the reference Grade 3 lesson plan):
${measuredPaletteBrief(resolveMeasuredPalette('Life Skills', 'worksheet'))}
- Every block is a large rounded card (${MEASURED_LAYOUT.cardRadius}) with a 2–4 px playful border on a very light ground; blocks are separated by ${MEASURED_LAYOUT.blockGap}.
- Section headings carry their emoji: 🎯 Aim of the Lesson · 🎒 Resources Needed · 🧠 Prior Knowledge & Preparation · 📑 Core Content & Key Concepts · ⏰ Lesson Procedure · 💙 Inclusive Education & Differentiation · 📝 Teacher Reflection Notes.
- Phase labels are amber pill chips: "Phase 1: Introduction & Hook (15 Minutes)".
- The CAPS Connection callout is a pale amber rounded box with a 💡 icon and a bold label.
- The Emergency / Golden Rule callout is a pale red rounded box with a 🚨 icon and the rule in one line.`,
  anatomy: LESSON_PLAN_CONTENT_CONTRACT,
  banner: 'self',
  extra: `LENGTH: a complete lesson plan is long — expect 1 500–2 500 words of teaching content plus the worksheet. Write it all. Never compress a phase to a bullet list.

THE PLAN IS FOR THE TEACHER, NOT THE LEARNER:
- Use "The teacher…" and "Learners will…".
- Include the exact words the teacher says, in quotation marks, for every phase where the teacher speaks.
- Every number, name and instruction the teacher needs is written out — never "prepare materials as needed".`,
});

export const lessonPlanTemplate: ContentTypeTemplate = {
  id: 'lesson-plan',
  aliases: [
    'lesson plan',
    'daily lesson notes',
    'weekly lesson plan',
    'unit plan',
    'caps lesson plan',
    'lesson-plan',
  ],
  title: 'CAPS Lesson Plan',
  purpose:
    "A full teacher lesson plan: banner, aim, resources, prior knowledge with a CAPS connection, core concepts with a golden rule, five timed procedure phases with spoken scripts, differentiation, reflection space and an optional appended worksheet.",
  sources: ['GFr3LPFull_Copy.pdf (supplied reference, 5 pages, Grade 3 Life Skills)'],
  sections: [
    { id: 'banner', heading: 'Banner', content: 'Three pills, topic H1, "Topic: …" subtitle, date · duration · class size row.' },
    { id: 'aim', heading: '🎯 Aim of the Lesson', content: 'Lead-in sentence plus exactly four measurable ✓ objectives.' },
    { id: 'resources', heading: '🎒 Resources Needed', content: 'For the Teacher and For the Learners bullet lists.' },
    { id: 'prior', heading: '🧠 Prior Knowledge & Preparation', content: 'Preparation paragraph plus the 💡 CAPS Connection callout.' },
    { id: 'core', heading: '📑 Core Content & Key Concepts', content: 'Numbered concept cards with "Action:" paragraphs plus the 🚨 rule callout.' },
    { id: 'procedure', heading: '⏰ Lesson Procedure', content: 'Five timed phases with spoken scripts and named scenarios.' },
    { id: 'inclusive', heading: '💙 Inclusive Education & Differentiation', content: 'Struggling and advanced learner cards.' },
    { id: 'reflection', heading: '📝 Teacher Reflection Notes', content: 'Dashed writing box with two guiding questions.' },
    { id: 'worksheet', heading: 'Appended learner worksheet', content: 'Four-question, 15-mark worksheet — only when requested.' },
  ] as ContentTypeTemplate['sections'],
  visual: {
    bannerGradient: 'subject palette, two stops',
    paletteId: 'lesson',
    gradeBadge: 'grade pill inside the banner ("LIFE SKILLS: GRADE 3")',
    sectionBar: 'emoji-led section headings inside rounded cards',
    scoreCard: 'the appended worksheet carries "SCORE ______ / 15"',
    typography: 'H1 32–36 px display; section headings 20–24 px; body 14–15 px',
    footer: MEASURED_LAYOUT.footer,
  },
  fixedCopy: [
    'CAPS ALIGNED',
    'TERM',
    'WEEK',
    'Topic:',
    'Duration:',
    'Class Size:',
    'At the end of this lesson, learners will be able to:',
    'For the Teacher:',
    'For the Learners:',
    'Prior Knowledge & Preparation',
    'CAPS Connection:',
    'Core Content & Key Concepts',
    'Action:',
    'Emergency Rule:',
    'Lesson Procedure',
    'Inclusive Education & Differentiation',
    'For Struggling Learners:',
    'For Advanced Learners:',
    'Teacher Reflection Notes',
    'Use this space to reflect on the success of the lesson:',
  ],
  blankFields: ['Date', 'Class size', 'Score', 'Teacher signature'],
  guardrails: [
    'All five procedure phases must be present, in order, with minute allocations.',
    'The CAPS Connection callout must name the CAPS sub-field.',
    'The plan carries exactly four objectives.',
    'The appended worksheet is generated only when the caller asks for it, and its marks add to its stated total.',
  ],
  systemPrompt,
  buildUserPrompt: (input: TemplatePromptInput) => {
    const phases = scaleLessonPhases(input.duration);
    const totalMinutes = phases.reduce((sum, phase) => sum + phase.minutes, 0);
    const includeWorksheet = /yes|true|include/i.test(String(input.additionalInstructions || ''))
      || false;

    return composeUserPrompt({
      requestBlock: requestBlock({
        grade: input.grade,
        subject: input.subject,
        topic: input.topic,
        term: input.term,
        week: input.week,
        duration: input.duration || '2 hours',
        classSize: input.classSize || 35,
        language: input.language,
        objectives: input.objectives,
        resources: input.resources,
        learnerProfile: input.learnerProfile,
      }),
      brief: `Write the complete lesson plan for this request.

PHASE TIMETABLE FOR THIS LESSON (${totalMinutes} minutes total — use these exact phase names and minutes):
${lessonPhaseTable(input.duration || '2 hours')}

SUMMARY OF THE CONTRACT YOU MUST SATISFY (the full contract is in your system prompt):
- Eight blocks, in order: Banner · Aim · Resources · Prior Knowledge · Core Content · Procedure · Inclusive Education · Teacher Reflection.
- Four ✓ objectives, each observable and each beginning with a verb (Identify / Recall / Demonstrate / Differentiate / Explain / Apply / Compare).
- Resources split into "For the Teacher:" (textbook with page numbers, demonstration kit, charts) and "For the Learners:" (workbooks, writing materials, handout).
- Core Content: three to five numbered concept cards, each with an "Action:" paragraph, plus one 🚨 rule callout.
- The five phases carry: a spoken hook script, physical demonstration objects, two named scenarios, the worksheet distribution instruction, and the closing game with its questions and answers.
- Inclusive Education: two cards, "For Struggling Learners:" and "For Advanced Learners:", each with 2–3 concrete bullets.
- Teacher Reflection: the heading "📝 Teacher Reflection Notes (Year ${new Date().getFullYear()})", the lead-in sentence, and a dashed box with two lesson-specific guiding questions.

${includeWorksheet ? LESSON_PLAN_WORKSHEET_CONTRACT : 'DO NOT append a learner worksheet to this plan — the teacher did not request one. The "memo" field carries the answer key for the concept work; the "rubric" field carries the observation rubric for the five phases.'}

${illustrationClause({
        generateImage: input.generateImage,
        style: input.illustrationStyle,
        goldenRule: input.imageGoldenRule,
      })}`,
      language: input.language,
      additionalInstructions: input.additionalInstructions,
    });
  },
};

export default lessonPlanTemplate;
